import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        int m = n;
        long[] b = new long[n];
        while (true) {
            int k = 0;
            for (int i = 0; i < m; i++)
                if (i == 0 || i == m - 1 || (a[i] > a[i - 1] && a[i] > a[i + 1])) b[k++] = a[i];
            if (k == m) break;  // nothing removed: stable
            long[] t = a;
            a = b;
            b = t;
            m = k;
        }
        StringBuilder out = new StringBuilder().append(m);
        for (int i = 0; i < m; i++) out.append(' ').append(a[i]);
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	b := make([]int64, 0, n)
	for {
		b = b[:0]
		m := len(a)
		for i, x := range a {
			if i == 0 || i == m-1 || (x > a[i-1] && x > a[i+1]) {
				b = append(b, x)
			}
		}
		if len(b) == m { // nothing removed: stable
			break
		}
		a, b = b, a
	}
	out := strconv.AppendInt(nil, int64(len(a)), 10)
	for _, x := range a {
		out = append(out, ' ')
		out = strconv.AppendInt(out, x, 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
